    entrypoint: str,
    case: TestCase,
    default_abs_tol: float | None,
) -> bool:
    compiler = shutil.which("g++") or shutil.which("clang++")
    if compiler is None:
        raise ExecutionSetupError("C++ compiler not found")
    try:
        source = build_cpp_driver(solution_path, entrypoint, case, default_abs_tol)
    except (OSError, TargetCodegenError):
        return False
    with tempfile.TemporaryDirectory() as tmp:
        tmp_path = Path(tmp)
        driver = tmp_path / "driver.cpp"
        binary = tmp_path / "driver"
        driver.write_text(source, encoding="utf-8")
        try:
            compile_proc = subprocess.run(
                [compiler, "-std=c++17", "-O0", str(driver), "-o", str(binary)],
