    default_abs_tol: float | None,
) -> bool:
    compiler = shutil.which("rustc")
    if compiler is None:
        raise ExecutionSetupError("Rust compiler not found")
    try:
        source = build_rust_driver(solution_path, entrypoint, case, default_abs_tol)
    except (OSError, TargetCodegenError):
        return False
    with tempfile.TemporaryDirectory() as tmp:
        tmp_path = Path(tmp)
        driver = tmp_path / "driver.rs"
        binary = tmp_path / "driver"
        driver.write_text(source, encoding="utf-8")
        try:
            compile_proc = subprocess.run(
                [compiler, "--edition=2021", str(driver), "-o", str(binary)],
                text=True,
                capture_output=True,
                timeout=20,
            )
        except (OSError, subprocess.TimeoutExpired) as exc:
            raise ExecutionSetupError("Rust compilation failed") from exc
        if compile_proc.returncode != 0:
